package com.dbconsole.platform.config;

import com.dbconsole.platform.entity.Instance;
import com.dbconsole.platform.entity.InstanceGroup;
import com.dbconsole.platform.entity.User;
import com.dbconsole.platform.mapper.InstanceGroupMapper;
import com.dbconsole.platform.mapper.InstanceMapper;
import com.dbconsole.platform.mapper.UserMapper;
import org.springframework.boot.CommandLineRunner;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;
import java.util.List;

/**
 * Seeds baseline users, groups, and one instance after the schema has been created.
 * Every block is guarded by a per-table emptiness check so restarts never duplicate rows.
 */
@Component
public class DataInitializer implements CommandLineRunner {

    private final UserMapper userMapper;
    private final InstanceGroupMapper groupMapper;
    private final InstanceMapper instanceMapper;
    private final PasswordEncoder passwordEncoder;

    public DataInitializer(UserMapper userMapper,
                           InstanceGroupMapper groupMapper,
                           InstanceMapper instanceMapper,
                           PasswordEncoder passwordEncoder) {
        this.userMapper = userMapper;
        this.groupMapper = groupMapper;
        this.instanceMapper = instanceMapper;
        this.passwordEncoder = passwordEncoder;
    }

    @Override
    public void run(String... args) {
        if (userMapper.countAll() == 0) {
            insertUser("admin", "admin123", "ADMIN");
            insertUser("user1", "user123", "USER");
            insertUser("user2", "user123", "USER");
        }
        if (groupMapper.countAll() == 0) {
            User admin = userMapper.findByUsername("admin");
            User user1 = userMapper.findByUsername("user1");
            if (admin != null && user1 != null) {
                insertGroup("默认分组", "默认实例分组", admin.getId());
                insertGroup("测试环境", "测试环境实例", user1.getId());
            }
        }
        if (instanceMapper.countAll() == 0) {
            User user1 = userMapper.findByUsername("user1");
            List<InstanceGroup> groups = groupMapper.findAll();
            if (user1 != null && !groups.isEmpty()) {
                insertInstance(groups.get(0).getId(), user1.getId());
            }
        }
    }

    private void insertUser(String username, String rawPassword, String role) {
        User user = new User();
        user.setUsername(username);
        user.setPassword(passwordEncoder.encode(rawPassword));
        user.setRole(role);
        user.setCreatedAt(LocalDateTime.now());
        userMapper.insert(user);
    }

    private void insertGroup(String name, String description, Long ownerId) {
        InstanceGroup group = new InstanceGroup();
        group.setName(name);
        group.setDescription(description);
        group.setOwnerId(ownerId);
        group.setCreatedAt(LocalDateTime.now());
        groupMapper.insert(group);
    }

    private void insertInstance(Long groupId, Long ownerId) {
        Instance instance = new Instance();
        instance.setName("内部MySQL");
        instance.setDbType("MYSQL");
        instance.setHost("mysql.internal.com");
        instance.setPort(3306);
        instance.setSchemaName("app_db");
        instance.setAccount("root");
        instance.setGroupId(groupId);
        instance.setStatus("CREATED");
        instance.setOwnerId(ownerId);
        LocalDateTime now = LocalDateTime.now();
        instance.setCreatedAt(now);
        instance.setUpdatedAt(now);
        instanceMapper.insert(instance);
    }
}

package com.dbconsole.platform.config;

import com.dbconsole.platform.security.JwtAuthenticationFilter;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.boot.web.servlet.FilterRegistrationBean;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpMethod;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    private final JwtAuthenticationFilter jwtAuthenticationFilter;

    public SecurityConfig(JwtAuthenticationFilter jwtAuthenticationFilter) {
        this.jwtAuthenticationFilter = jwtAuthenticationFilter;
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
                .csrf(AbstractHttpConfigurer::disable)
                .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers(HttpMethod.POST, "/api/auth/login").permitAll()
                        .anyRequest().authenticated())
                .exceptionHandling(ex -> ex.authenticationEntryPoint((request, response, authException) ->
                        response.setStatus(HttpServletResponse.SC_UNAUTHORIZED)))
                .addFilterBefore(jwtAuthenticationFilter, UsernamePasswordAuthenticationFilter.class);
        return http.build();
    }

    /**
     * The JWT filter runs inside the Spring Security filter chain only; the bean is
     * excluded from automatic servlet registration so it cannot run out of order.
     */
    @Bean
    public FilterRegistrationBean<JwtAuthenticationFilter> jwtAuthenticationFilterRegistration() {
        FilterRegistrationBean<JwtAuthenticationFilter> registration =
                new FilterRegistrationBean<>(jwtAuthenticationFilter);
        registration.setEnabled(false);
        return registration;
    }
}

package com.dbconsole.platform.controller;

import com.dbconsole.platform.dto.ApiResponse;
import com.dbconsole.platform.dto.LoginRequest;
import com.dbconsole.platform.service.AuthService;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final AuthService authService;

    public AuthController(AuthService authService) {
        this.authService = authService;
    }

    @PostMapping("/login")
    public ResponseEntity<ApiResponse<AuthService.LoginResult>> login(@RequestBody LoginRequest request) {
        AuthService.LoginResult result = authService.login(request.getUsername(), request.getPassword());
        if (result == null) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(ApiResponse.error(401, "用户名或密码错误"));
        }
        return ResponseEntity.ok(ApiResponse.success("登录成功", result));
    }
}

package com.dbconsole.platform.controller;

import com.dbconsole.platform.dto.ApiResponse;
import com.dbconsole.platform.dto.CreateGroupRequest;
import com.dbconsole.platform.entity.InstanceGroup;
import com.dbconsole.platform.entity.User;
import com.dbconsole.platform.service.GroupService;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

@RestController
@RequestMapping("/api/groups")
public class GroupController {

    private final GroupService groupService;

    public GroupController(GroupService groupService) {
        this.groupService = groupService;
    }

    @PostMapping
    public ApiResponse<InstanceGroup> create(@RequestBody CreateGroupRequest request) {
        return ApiResponse.success("创建成功", groupService.create(request, currentUser()));
    }

    @GetMapping
    public ApiResponse<List<InstanceGroup>> list() {
        return ApiResponse.success(groupService.list(currentUser()));
    }

    @DeleteMapping("/{id}")
    public ApiResponse<Void> delete(@PathVariable Long id) {
        GroupService.DeleteOutcome outcome = groupService.delete(id, currentUser());
        return switch (outcome) {
            case DELETED -> ApiResponse.success("删除成功", null);
            case NOT_FOUND -> ApiResponse.error(404, "分组不存在");
            case HAS_INSTANCES -> ApiResponse.error(400, "分组下存在实例，无法删除");
        };
    }

    private User currentUser() {
        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
        if (authentication != null && authentication.getPrincipal() instanceof User user) {
            return user;
        }
        throw new IllegalStateException("No authenticated user in security context");
    }
}

package com.dbconsole.platform.controller;

import com.dbconsole.platform.dto.ApiResponse;
import com.dbconsole.platform.dto.CreateInstanceRequest;
import com.dbconsole.platform.dto.UpdateInstanceRequest;
import com.dbconsole.platform.entity.Instance;
import com.dbconsole.platform.entity.User;
import com.dbconsole.platform.service.InstanceService;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/instances")
public class InstanceController {

    private final InstanceService instanceService;

    public InstanceController(InstanceService instanceService) {
        this.instanceService = instanceService;
    }

    @PostMapping
    public ApiResponse<Instance> register(@RequestBody CreateInstanceRequest request) {
        return ApiResponse.success("注册成功", instanceService.create(request, currentUser()));
    }

    @GetMapping
    public ApiResponse<List<Instance>> list(@RequestParam(required = false) String dbType,
                                            @RequestParam(required = false) Long groupId) {
        return ApiResponse.success(instanceService.list(dbType, groupId, currentUser()));
    }

    @GetMapping("/{id}")
    public ApiResponse<Instance> detail(@PathVariable Long id) {
        Instance instance = instanceService.get(id, currentUser());
        if (instance == null) {
            return ApiResponse.error(404, "实例不存在");
        }
        return ApiResponse.success(instance);
    }

    @PutMapping("/{id}")
    public ApiResponse<Instance> update(@PathVariable Long id, @RequestBody UpdateInstanceRequest request) {
        Instance instance = instanceService.update(id, request, currentUser());
        if (instance == null) {
            return ApiResponse.error(404, "实例不存在");
        }
        return ApiResponse.success("更新成功", instance);
    }

    @DeleteMapping("/{id}")
    public ApiResponse<Void> delete(@PathVariable Long id) {
        boolean deleted = instanceService.delete(id, currentUser());
        if (!deleted) {
            return ApiResponse.error(404, "实例不存在");
        }
        return ApiResponse.success("删除成功", null);
    }

    @PostMapping("/{id}/ping")
    public ApiResponse<Map<String, Object>> ping(@PathVariable Long id) {
        Map<String, Object> outcome = instanceService.ping(id, currentUser());
        if (outcome == null) {
            return ApiResponse.error(404, "实例不存在");
        }
        return ApiResponse.success("连通测试完成", outcome);
    }

    private User currentUser() {
        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
        if (authentication != null && authentication.getPrincipal() instanceof User user) {
            return user;
        }
        throw new IllegalStateException("No authenticated user in security context");
    }
}

